import { AppError, createLogger, getAppUrl } from "@chopnow/lib";

const log = createLogger("paystack");

const PAYSTACK_BASE_URL = "https://api.paystack.co";

export interface InitializeTransactionInput {
  email: string;
  /** Amount in kobo (Paystack's smallest currency unit — ₦1 = 100 kobo). */
  amountKobo: number;
  orderId: string;
  orderNumber: string;
  /** Pre-generated by the caller so the order row can store it before
   *  Paystack is ever contacted — see lib/actions/orders.ts for why. */
  reference: string;
}

export interface InitializeTransactionResult {
  authorizationUrl: string;
  accessCode: string;
  reference: string;
}

/**
 * Initializes a Paystack transaction and returns the hosted checkout URL
 * to redirect the customer to. This function only *starts* payment — it
 * never marks anything as paid. The only code path allowed to do that is
 * the webhook handler (app/api/webhooks/paystack/route.ts), which
 * verifies Paystack's signature before trusting the event, per PRD
 * Section 7.8 / FR-PAY-02.
 *
 * The callback_url below points at a thin confirmation page
 * (/checkout/confirming) that shows a spinner and polls order status —
 * it does NOT itself confirm payment. See that page's comments for why.
 */
export async function initializePaystackTransaction(
  input: InitializeTransactionInput,
): Promise<InitializeTransactionResult> {
  const secretKey = process.env.PAYSTACK_SECRET_KEY;
  if (!secretKey) {
    throw AppError.internal(
      "Payment processing is not configured. Set PAYSTACK_SECRET_KEY in the environment.",
    );
  }

  const callbackUrl = `${getAppUrl("web")}/checkout/confirming?order=${input.orderId}`;

  let response: Response;
  try {
    response = await fetch(`${PAYSTACK_BASE_URL}/transaction/initialize`, {
      method: "POST",
      headers: {
        Authorization: `Bearer ${secretKey}`,
        "Content-Type": "application/json",
      },
      body: JSON.stringify({
        email: input.email,
        amount: input.amountKobo,
        reference: input.reference,
        callback_url: callbackUrl,
        metadata: {
          order_id: input.orderId,
          order_number: input.orderNumber,
        },
      }),
    });
  } catch (err) {
    log.error("Paystack initialize request failed (network)", err, { orderId: input.orderId });
    throw AppError.internal("Could not reach the payment provider. Please try again.");
  }

  const body = await response.json().catch(() => null);

  if (!response.ok || !body?.status) {
    log.error("Paystack initialize returned an error", undefined, {
      orderId: input.orderId,
      status: response.status,
      body,
    });
    throw AppError.paymentFailed(body?.message || "Could not start payment. Please try again.");
  }

  return {
    authorizationUrl: body.data.authorization_url,
    accessCode: body.data.access_code,
    reference: body.data.reference,
  };
}

/**
 * Fetches a transaction's current status directly from Paystack's API
 * (as opposed to trusting the webhook payload alone) — used by the
 * webhook handler as a defense-in-depth double-check, and by the
 * `/checkout/confirming` polling page as a fallback if the webhook is
 * slow to arrive.
 */
export async function verifyPaystackTransaction(reference: string): Promise<{
  status: "success" | "failed" | "abandoned" | "pending";
  amountKobo: number;
  orderId: string | undefined;
}> {
  const secretKey = process.env.PAYSTACK_SECRET_KEY;
  if (!secretKey) {
    throw AppError.internal("Payment processing is not configured.");
  }

  const response = await fetch(`${PAYSTACK_BASE_URL}/transaction/verify/${encodeURIComponent(reference)}`, {
    headers: { Authorization: `Bearer ${secretKey}` },
  });

  const body = await response.json().catch(() => null);

  if (!response.ok || !body?.status) {
    throw AppError.internal("Could not verify payment status with Paystack.");
  }

  return {
    status: body.data.status,
    amountKobo: body.data.amount,
    orderId: body.data.metadata?.order_id,
  };
}
